mapper.insert:
insert into T_GLUE_WORKMANSHIP (id,FACTORY_CODE,GLUE,KNIFE_NUM,CAR_NUM,REMARK,DEL_FLAG,create_by,create_time) select NULL id, x.* from (
select #{glueWorkmanship.factoryCode,jdbcType=VARCHAR} FACTORY_CODE, #{glueWorkmanship.glue,jdbcType=VARCHAR} GLUE, #{glueWorkmanship.knifeNum,jdbcType=NUMERIC} KNIFE_NUM, #{glueWorkmanship.carNum,jdbcType=NUMERIC} CAR_NUM, #{glueWorkmanship.remark,jdbcType=VARCHAR} REMARK, #{glueWorkmanship.delFlag,jdbcType=VARCHAR} DEL_FLAG, #{glueWorkmanship.createBy,jdbcType=VARCHAR} CREATE_BY, #{glueWorkmanship.createTime,jdbcType=TIMESTAMP} CREATE_TIME
) x

mapper.update:
merge into T_GLUE_WORKMANSHIP a using(
select #{glueWorkmanship.factoryCode,jdbcType=VARCHAR} FACTORY_CODE, #{glueWorkmanship.glue,jdbcType=VARCHAR} GLUE, #{glueWorkmanship.knifeNum,jdbcType=NUMERIC} KNIFE_NUM, #{glueWorkmanship.carNum,jdbcType=NUMERIC} CAR_NUM, #{glueWorkmanship.remark,jdbcType=VARCHAR} REMARK, #{glueWorkmanship.createBy,jdbcType=VARCHAR} CREATE_BY, #{glueWorkmanship.createTime,jdbcType=TIMESTAMP} CREATE_TIME
) b on( a.FACTORY_CODE=b.FACTORY_CODE and a.GLUE=b.GLUE and a.DEL_FLAG='0' ) when matched then update set a.KNIFE_NUM=b.KNIFE_NUM, a.CAR_NUM=b.CAR_NUM, a.REMARK=b.REMARK, a.UPDATE_BY=b.CREATE_BY, a.UPDATE_TIME=now() when not matched then insert( a.ID, a.FACTORY_CODE, a.GLUE, a.KNIFE_NUM, a.CAR_NUM, a.REMARK, a.DEL_FLAG, a.CREATE_BY, a.CREATE_TIME ) values( get_sequence_nextval('SEQ_T_GLUE_WORKMANSHIP'), b.FACTORY_CODE, b.GLUE, b.KNIFE_NUM, b.CAR_NUM, b.REMARK, '0', b.CREATE_BY, now() )

mapper.select:
WITH temp_table AS (
SELECT #{rowNumber}+2 row_numbers, #{data.factoryCode,jdbcType=VARCHAR} FACTORY_CODE,#{data.glue,jdbcType=VARCHAR} GLUE
) select #{importLogId} importLogId, t.row_numbers errorRow, #{errorDetail} errorDetail, #{createBy} createBy, now() createTime from T_GLUE_WORKMANSHIP m inner join temp_table t on m.FACTORY_CODE = t.FACTORY_CODE and m.GLUE=t.GLUE and m.del_flag ='0'

select id, FACTORY_CODE, GLUE, KNIFE_NUM,CAR_NUM, remark, del_flag, create_by, create_time, update_by, update_time from T_GLUE_WORKMANSHIP where del_flag = '0' and FACTORY_CODE=#{factoryCode} and INSTR(glue, #{glue}) > 0
order by create_time desc
order by ${orderStr}
